      "concern_id": "C18",
      "effect": "moves",
      "direction": "Decreases the regulatory reach of local government",
      "quote": "A city may not require a public hearing to approve a project that meets this section.",
      "mechanism": "Removes the local government's power to mandate public hearings for these projects.",
      "certainty": "stated"
